"""Renders docs/ENROLLMENT_PASSAGES.md from the one file that holds the passage text.

Edit backend/app/content/enrollment_passages.json, never the markdown, then run:
    python scripts/render_passages_doc.py
"""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / "backend" / "app" / "content" / "enrollment_passages.json"
TARGET = ROOT / "docs" / "ENROLLMENT_PASSAGES.md"

HEADER = """# Enrollment Passages

<!-- GENERATED by scripts/render_passages_doc.py from backend/app/content/enrollment_passages.json.
     Do not edit this file; edit the JSON and re-run the script. -->

Three passages a user reads aloud during voice enrollment, one per `enrollment_samples.language`
value (`en` / `ur` / `mixed`, see DATA_MODEL.md). Each is sized to take about 20 to 25 seconds at a
natural, unhurried conversational pace, so that the quality gate's minimum of {minimum:.0f} seconds
of detected speech is reached without rushing. Read each one aloud once to feel the timing. Full
rationale for three passages in three languages is in
`docs/adr/0012-three-passage-bilingual-enrollment.md`, and for the {minimum:.0f} second minimum in
`docs/adr/0013-enrollment-quality-gate.md`.

Content is deliberately mundane: nothing that reads as a form, no names, no numbers, nothing
personally identifying. Passage wording does not affect a stored voiceprint, so changing it never
forces anyone to re-enroll.

The app, the dev harness and this document all read the same JSON file; there is no other copy of
the text.

---
"""


def main() -> None:
    content = json.loads(SOURCE.read_text(encoding="utf-8"))
    parts = [HEADER.format(minimum=content["min_speech_seconds"])]

    for number, passage in enumerate(content["passages"], start=1):
        lines = [f"## {number}. {passage['title']}", "", f"> {passage['text']}", ""]

        if passage["transliteration"]:
            lines += [f"**Transliteration:** {passage['transliteration']}", ""]

        if passage["meaning"]:
            lines += [f"**Meaning:** {passage['meaning']}", ""]

        word_count = len(passage["text"].split())
        lines += [f"**Length:** {word_count} words.", "", f"**Notes:** {passage['notes']}", "", "---", ""]
        parts.append("\n".join(lines))

    TARGET.write_text("\n".join(parts), encoding="utf-8")
    print(f"wrote {TARGET}")


if __name__ == "__main__":
    main()
